+    for &watch in &watch.boundaries {
+        match template.boundary(watch).resolve(text, eof) {
+            Resolution::Pending => return incomplete(),
+            Resolution::NoMatch => {}
+            Resolution::Matched { len, captures } => {
+                let candidate = BoundaryMatch {
+                    watch,
+                    len,
+                    captures,
