+                "content_args": {
+                    "tag_pattern": r#"<param\b[^>]*?\bname="(?P<key>[^"]+)"[^>]*?>(?P<value>.*?)</param>"#,
+                    "value_parser": {"name": "json", "args": {"allow_non_json": true}},
+                },
+                "transform": {"type": "function", "function": {"name": "{name}", "arguments": "{content}"}},
+            },
+            "content": {
+                "open_pattern": r"to=(?:user|note)<\|msg\|>",
+                "close": ["<|end|>", "<|pause|>"],
+                "repeats": true,
+                "join": "",
+                "content": "text",
